// TOTAL HQ — worker v1
// Parent hub for the HQ family. Serves the board of properties and the shared
// registry (/registry.json) that every child site can read instead of hardcoding.

const REGISTRY = {
  updated: "2026-10-22",
  parent: { name: "Total HQ", url: "https://total-hq.com" },
  boards: [
    { key:"mlb", league:"MLB", name:"Moonshot HQ",  word:"Moonshot",  icon:"⚾", cadence:"Daily",  status:"live", url:"https://moonshot-hq.com",  accent:"#FFC24B" },
    { key:"nfl", league:"NFL", name:"Touchdown HQ", word:"Touchdown", icon:"🏈", cadence:"Weekly", status:"live", url:"https://touchdown-hq.com", accent:"#FF4D3D" },
    { key:"nhl", league:"NHL", name:"Slapshot HQ",  word:"Slapshot",  icon:"🏒", cadence:"Daily",  status:"live", url:"https://slapshot-hq.com",  accent:"#7CC8FF" },
    { key:"nba", league:"NBA", name:"Slam HQ",      word:"Slam",      icon:"🏀", cadence:"Daily",  status:"live", url:"https://slam-hq.com",      accent:"#FF8A3D" }
  ]
};

const OG_PNG = "";
const TOUCH_ICON = "";
const FAVICON = "";
function pngResponse(b64data) {
  const bin = atob(b64data);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, { headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400" } });
}
function serveAsset(path) {
  if (path === "/og.png") return pngResponse(OG_PNG);
  if (path === "/apple-touch-icon.png") return pngResponse(TOUCH_ICON);
  if (path === "/favicon.png" || path === "/favicon.ico") return pngResponse(FAVICON);
  return null;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const path = url.pathname;

    const asset = serveAsset(path);
    if (asset) return asset;

    if (path === "/registry.json") {
      return new Response(JSON.stringify(REGISTRY), {
        headers: {
          "Content-Type": "application/json; charset=utf-8",
          "Cache-Control": "public, max-age=3600",
          "Access-Control-Allow-Origin": "*"
        }
      });
    }

    return new Response(HTML.split("__ORIGIN__").join(url.origin), {
      headers: { "Content-Type": "text/html; charset=utf-8" }
    });
  }
};

const HTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>TOTAL HQ — Every Sport, Scored 0–100</title>
<meta name="description" content="One board per sport. Every player on the slate, scored 0 to 100.">
<meta property="og:title" content="TOTAL HQ — Every Sport, Scored 0–100">
<meta property="og:description" content="One board per sport. Every player on the slate, scored 0 to 100.">
<meta property="og:image" content="__ORIGIN__/og.png">
<meta property="og:url" content="__ORIGIN__">
<meta property="og:type" content="website">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:image" content="__ORIGIN__/og.png">
<meta name="theme-color" content="#08090C">
<link rel="icon" type="image/png" href="/favicon.png">
<link rel="apple-touch-icon" href="/apple-touch-icon.png">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@600;700;800&family=Space+Grotesk:wght@400;500;700&display=swap" rel="stylesheet">
<style>
:root{
  --void:#08090C;
  --hq:#FF4D3D;
  --paper:#EDEAE3;
  --mute:#767C86;
  --dim:#454B55;
  --rule:rgba(255,255,255,.075);
  --lift:rgba(255,255,255,.035);
}
*{box-sizing:border-box;margin:0;padding:0}
html{background:var(--void)}
body{
  background:
    radial-gradient(1300px 680px at 50% -18%, rgba(237,234,227,.075), transparent 64%),
    var(--void);
  background-attachment:fixed;
  color:var(--paper);
  font-family:'Space Grotesk',system-ui,sans-serif;
  -webkit-font-smoothing:antialiased;
  min-height:100vh;
}
*{-webkit-tap-highlight-color:transparent}
.wrap{max-width:720px;margin:0 auto;padding:0 20px 44px}

/* ---------- masthead ---------- */
header{padding:56px 0 0}
.eyebrow{font-size:10px;letter-spacing:.26em;text-transform:uppercase;color:var(--dim);font-weight:500}
.rule{height:1px;background:var(--rule);margin:14px 0 30px}
h1{font-family:'Big Shoulders Display',sans-serif;font-weight:800;font-size:clamp(52px,15vw,86px);
   line-height:.86;letter-spacing:.005em;display:flex;align-items:center;gap:14px;flex-wrap:wrap}
h1 .badge{background:none;color:var(--hq);font-size:1em;font-weight:800;
   padding:0;border:0;border-radius:0;letter-spacing:.015em;line-height:inherit;
   vertical-align:baseline;transform:none;margin-left:.06em}
.thesis{margin-top:20px;color:var(--mute);font-size:15px;line-height:1.6;max-width:44ch}
.thesis b{color:var(--paper);font-weight:500}

/* ---------- the board ---------- */
.boardhead{display:grid;grid-template-columns:3px 52px 1fr auto;align-items:center;gap:0 16px;
  margin:44px 0 0;font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--dim);
  padding:0 2px 10px;border-bottom:1px solid var(--rule)}
.boardhead .hl{grid-column:1 / 3}
.boardhead .hb{grid-column:3}
.boardhead .hs{grid-column:4;text-align:right;padding-right:10px}
.lane{
  display:grid;grid-template-columns:3px 52px 1fr auto;align-items:center;gap:0 16px;
  padding:17px 2px;border-bottom:1px solid var(--rule);
  text-decoration:none;color:inherit;position:relative;
  transition:background .28s cubic-bezier(.4,0,.2,1);
}
.lane .bar{grid-column:1;align-self:stretch;border-radius:2px;background:var(--accent);
  opacity:.22;transition:opacity .28s ease}
.lane .lg{grid-column:2;font-size:10px;letter-spacing:.13em;color:var(--dim);
  font-variant-numeric:tabular-nums}
.lane .nm{grid-column:3;font-family:'Big Shoulders Display',sans-serif;font-weight:700;
  font-size:27px;line-height:1;letter-spacing:.01em;display:flex;align-items:baseline;gap:11px}
.lane .nm em{font-style:normal;font-family:'Space Grotesk',sans-serif;font-size:10.5px;
  font-weight:400;letter-spacing:.13em;text-transform:uppercase;color:var(--dim)}
.lane .st{grid-column:4;font-size:9.5px;letter-spacing:.19em;text-transform:uppercase;
  color:var(--dim);white-space:nowrap;display:flex;align-items:center;gap:9px}
.lane .st .arw{display:inline-block;transition:transform .28s cubic-bezier(.4,0,.2,1);font-size:13px}

.lane.live{cursor:pointer}
.lane.live .bar{opacity:1}
.lane.live .nm{color:var(--paper)}
.lane.live .st{color:var(--accent)}
.lane.live:hover{background:var(--lift)}
.lane.live:hover .st .arw{transform:translateX(5px)}
.lane.live:focus-visible{outline:2px solid var(--open);outline-offset:-2px}
/* live status reads as one signal, not per-sport branding */
:root{--open:#4ADE80}
.lane.live .bar{background:var(--accent);box-shadow:0 0 12px var(--accent)}
.lane.live .st{color:var(--accent)}

.lane.build .nm{color:var(--dim)}
.lane.build .lg{color:#343941}

.soon{margin-top:18px;border-radius:14px;padding:30px 22px;text-align:center;
  background:linear-gradient(180deg,rgba(255,255,255,.035),rgba(255,255,255,.008));
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.06);
  transition:box-shadow .3s ease}
.soon:hover{box-shadow:inset 0 0 0 1px rgba(255,255,255,.12)}
.soon .t{font-family:'Big Shoulders Display',sans-serif;font-weight:700;font-size:23px;
  letter-spacing:.07em;color:var(--mute)}

footer{margin-top:32px;padding-top:18px;border-top:1px solid var(--rule);
  color:var(--dim);font-size:11.5px;line-height:1.7;max-width:52ch;text-wrap:pretty}

/* ---------- entrance ---------- */
.lane,.soon,footer{animation:rise .6s cubic-bezier(.2,.7,.3,1) backwards}
@keyframes rise{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:none}}

#xfade{position:fixed;inset:0;background:#08090C;z-index:9999;opacity:1;pointer-events:none;transition:opacity .32s ease}
#xfade.gone{opacity:0}

@media (max-width:520px){
  .lane,.boardhead{grid-template-columns:3px 44px 1fr auto;gap:0 12px}
  .lane .nm{font-size:23px;flex-direction:column;align-items:flex-start;gap:4px}
}
@media (prefers-reduced-motion:reduce){
  *{animation-duration:.01ms!important;transition-duration:.01ms!important}
  #xfade{transition:none}
}

/* ===== desktop only — nothing below 1024px ever reads this ===== */
@media (min-width:1024px){
  .wrap{max-width:clamp(820px,70vw,1180px)}
  h1{font-size:clamp(62px,5.2vw,96px)}
  .thesis{font-size:clamp(15px,1.1vw,19px);max-width:50ch}
  .lane{grid-template-columns:3px 64px 1fr auto;gap:0 20px;padding:21px 2px}
  .boardhead{grid-template-columns:3px 64px 1fr auto;gap:0 20px}
  .lane .nm{font-size:clamp(28px,2.1vw,36px)}
  .lane .lg,.lane .st,.boardhead{font-size:clamp(10px,.72vw,12px)}
  .soon .t{font-size:clamp(24px,1.8vw,30px)}
  footer{font-size:clamp(12px,.86vw,14px)}
}
</style>
</head>
<body>
<div id="xfade"></div>
<div class="wrap">

  <header>
    <div class="eyebrow">Every sport · Scored 0–100</div>
    <div class="rule"></div>
    <h1>TOTAL<span class="badge">HQ</span></h1>
    <p class="thesis">One board per sport. Every player on the slate, scored <b>0 to 100</b>.</p>
  </header>

  <div class="boardhead"><span class="hl">League</span><span class="hb">Board</span><span class="hs">Status</span></div>
  <div id="board"></div>

  <div class="soon"><div class="t">More sports coming soon</div></div>

  <footer>Each board reads the same way: one score, five tiers, every input shown.</footer>

  

</div>
<script>
"use strict";
var BOARDS = [{"key":"mlb","league":"MLB","name":"Moonshot HQ","word":"Moonshot","icon":"⚾","cadence":"Daily","status":"live","url":"https://moonshot-hq.com","accent":"#FFC24B"},{"key":"nfl","league":"NFL","name":"Touchdown HQ","word":"Touchdown","icon":"🏈","cadence":"Weekly","status":"live","url":"https://touchdown-hq.com","accent":"#FF4D3D"},{"key":"nhl","league":"NHL","name":"Slapshot HQ","word":"Slapshot","icon":"🏒","cadence":"Daily","status":"live","url":"https://slapshot-hq.com","accent":"#7CC8FF"},{"key":"nba","league":"NBA","name":"Slam HQ","word":"Slam","icon":"🏀","cadence":"Daily","status":"live","url":"https://slam-hq.com","accent":"#FF8A3D"}];

function esc(s){ return String(s).replace(/[&<>"']/g, function(c){
  return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }

function laneHTML(b, i){
  var live = b.status === "live";
  var tag  = live ? 'a href="' + esc(b.url) + '"' : 'div';
  var end  = live ? 'a' : 'div';
  return '<' + tag + ' class="lane ' + (live ? 'live' : 'build') + '"'
    + ' style="--accent:' + esc(b.accent) + ';animation-delay:' + (i * 55) + 'ms">'
    + '<span class="bar"></span>'
    + '<span class="lg">' + esc(b.league) + '</span>'
    + '<span class="nm">' + esc(b.word) + ' HQ <em>' + esc(b.cadence) + '</em></span>'
    + '<span class="st">' + (live ? 'Open <span class="arw">→</span>' : 'In build') + '</span>'
    + '</' + end + '>';
}

document.getElementById("board").innerHTML = BOARDS.map(laneHTML).join("");

(function(){
  function xf(){ return document.getElementById("xfade"); }
  function reveal(){ var e = xf(); if(e){ requestAnimationFrame(function(){ e.classList.add("gone"); }); } }
  window.addEventListener("pageshow", reveal);
  if(document.readyState !== "loading") reveal();
  document.addEventListener("click", function(ev){
    var t = ev.target, a = (t && t.closest) ? t.closest("a.lane") : null;
    if(!a) return;
    var href = a.getAttribute("href");
    if(!href) return;
    ev.preventDefault();
    var e = xf(); if(e) e.classList.remove("gone");
    setTimeout(function(){ location.href = href; }, 250);
  }, true);
})();
</script>
</body>
</html>`;
